export const getGetWeatherUrl = (params: GetWeatherParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    const explodeParameters = ["point"];

    if (Array.isArray(value) && explodeParameters.includes(key)) {
      value.forEach((v) => {
        normalizedParams.append(key, v === null ? "null" : String(v));
      });
      return;
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/weather?${stringifiedParams}` : `/v1/weather`;
};

export const getWeather = async (
  params: GetWeatherParams,
  options?: Parameters<typeof domestiqueRequest>[1],
): Promise<getWeatherResponseSuccess> => {
  return domestiqueRequest<getWeatherResponseSuccess>(getGetWeatherUrl(params), {
    ...options,
    method: "GET",
  });
};

